-- =============================================================================
-- SAP material group tree (reference data, never typed).
--
-- dim_material_group: every catalogue entry of the Material Cost Report tool, with
-- family = leading letters of the code (famOf), division = family + two digits when
-- the catalogue has it (realDiv; NULL where the family has no SAP division), and
-- sort_order = tree order (treeCmp). dim_material_family: the 17 families in the
-- tool's fixed order. Generated from the tool's own functions; do not hand-edit.
-- =============================================================================

CREATE TABLE dim_material_group (
  code       TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  family     TEXT,
  division   TEXT,
  sort_order INTEGER
);

CREATE TABLE dim_material_family (
  family     TEXT PRIMARY KEY,
  sort_order INTEGER NOT NULL
);


